'use strict';
window.NexoShell=(()=>{
const paths={bolt:'M13 2 4 14h7l-1 8 10-12h-7l1-8Z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',play:'m8 3 14 9-14 9V3Z',alert:'m10.3 3.8-8.5 14.3a2 2 0 0 0 1.7 3h17a2 2 0 0 0 1.7-3L13.7 3.8a2 2 0 0 0-3.4 0ZM12 9v4M12 17h.01',up:'m2 17 6-6 4 4L22 5M16 5h6v6',down:'m2 7 6 6 4-4 10 10M16 19h6v-6',server:'M3 3h18v7H3zM3 14h18v7H3zM6 6.5h.01M6 17.5h.01M10 6.5h8M10 17.5h8',screen:'M3 3h18v13H3zM8 21h8M12 16v5',chart:'m2 12 5 0 3-8 4 16 3-8h5',package:'m12 2 10 6v9l-10 6-10-6V8l10-6ZM2 8l10 6 10-6M12 14v9M7 5l10 6',tool:'M14.7 6.3a5.5 5.5 0 0 0-7-7l3 3-3 3-3-3a5.5 5.5 0 0 0 7 7l8 8a2.1 2.1 0 0 0 3-3l-8-8Z',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z'};
function icon(name,cls=''){return `<svg viewBox="0 0 24 24" class="ui-icon ${cls}" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.chart}"/></svg>`;}
let menuInit=false,lastData=null,lastMode='idle',lastStatus='idle';
function sync(d=null,mode='idle',st='idle'){if(arguments.length){lastData=d;lastMode=mode;lastStatus=st;}else{d=lastData;mode=lastMode;st=lastStatus;}
 const all=document.querySelectorAll('[data-shell-metric]');
 for(const node of all){const key=node.dataset.shellMetric;let value='—';if(key==='connections')value=d?.connections.established??'—';if(key==='lines')value=d?.sessions?d.sessions.length:'—';if(key==='streams')value=mode==='demo'?3:(d?.streaming?.live??'—');if(key==='down')value=mode==='demo'?0:(d?.streaming?.failed??'—');if(key==='traffic')value=d?rate(d.network.tx_bps)+' ↑ '+rate(d.network.rx_bps)+' ↓':'— ↑ — ↓';node.textContent=value;}
 const badge=document.querySelector('#shell-state');if(badge){badge.textContent=mode==='demo'?'DEMO':st==='online'?'EN DIRECTO':st==='offline'?'SIN RESPUESTA':'SIN AGENTE';badge.className='shell-state '+(mode==='demo'?'demo':st);}
 const filter=document.querySelector('#server-filter');if(filter){filter.options[0].textContent=window.NexoServers?.exportConfig().servers.length>1?'Servidor activo':'Todos los servidores';const value=filter.value;const option=filter.querySelector('[data-current-server]');if(d){if(option){option.value=d.server.id;option.textContent=d.server.name;}else{const o=document.createElement('option');o.dataset.currentServer='';o.value=d.server.id;o.textContent=d.server.name;filter.append(o);}}else if(option)option.remove();if(Array.from(filter.options).some(o=>o.value===value))filter.value=value;}
 document.querySelectorAll('[data-nav]').forEach(n=>{const page=(location.hash.slice(1)||'recursos');const group={recursos:'dashboard',conexiones:'dashboard',inicio:'dashboard',clientes:'lines',canales:'content',streaming:'content',paquetes:'bouquets',proyecto:'management',actualizaciones:'management',servers:'servers',proxies:'servers','server-order':'servers','process-monitor':'servers'}[page];n.classList.toggle('current',n.dataset.nav===group);});
}
function rate(n){if(!Number.isFinite(n))return '—';return (n/1e6).toLocaleString('es-EC',{maximumFractionDigits:1})+' Mbps';}
function search(){const input=document.querySelector('#global-search'),box=document.querySelector('#search-results');const text=input.value.trim().toLowerCase();if(!text){box.hidden=true;box.innerHTML='';return;}const sections=[['clients','Cliente','clientes'],['channels','Canal','canales'],['packages','Paquete','paquetes']];const hits=[];for(const [type,label,hash] of sections)for(const item of db[type])if(item.name.toLowerCase().includes(text))hits.push({name:item.name,type,label,hash,id:item.id});box.innerHTML=hits.length?hits.slice(0,12).map(r=>`<button type="button" data-search-type="${r.type}" data-search-id="${esc(r.id)}"><span>${esc(r.name)}</span><small>${r.label}</small></button>`).join(''):'<p>No hay coincidencias en el catálogo.</p>';box.hidden=false;}
document.addEventListener('DOMContentLoaded',()=>{
 if(menuInit)return;menuInit=true;
 const originHint=document.querySelector('#allowed-origin-hint');if(originHint)originHint.textContent=location.origin;
 const input=document.querySelector('#global-search');input.addEventListener('input',search);input.addEventListener('focus',search);
 document.addEventListener('click',e=>{if(!e.target.closest('.global-search'))document.querySelector('#search-results').hidden=true;const action=e.target.closest('[data-shell-action]');if(action){const name=action.dataset.shellAction;if(name==='backup')exportBackup();if(name==='import')restore();if(name==='new-client')edit('clients');if(name==='new-channel')edit('channels');if(name==='new-package')edit('packages');}const hit=e.target.closest('[data-search-id]');if(hit){edit(hit.dataset.searchType,hit.dataset.searchId);document.querySelector('#search-results').hidden=true;}document.querySelectorAll('details.nav-menu,details.account-menu,details.infra-header-tools').forEach(d=>{if(!d.contains(e.target)||e.target.closest('a,button'))d.open=false;});});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelectorAll('details[open]').forEach(d=>d.open=false);document.querySelector('#search-results').hidden=true;}});
 document.querySelectorAll('.nav-menu').forEach(d=>d.addEventListener('toggle',()=>{if(d.open)document.querySelectorAll('.nav-menu').forEach(other=>{if(other!==d)other.open=false;});}));
 document.querySelector('#server-filter').addEventListener('change',()=>NexoMonitor.draw());
 sync();
});
return {icon,sync};
})();
